export type GoogleResource = {
  title: string;
  url: string;
  access: "open" | "public-link";
  license: "CC BY 4.0 / Apache 2.0" | "Public link — verify resource terms" | "Apache 2.0";
  note: Localized;
};

export type GoogleUnit = {
  title: Localized;
  objective: Localized;
  practice: Localized;
};

export type GoogleLearningTrack = {
  id: string;
  order: number;
  domain: Localized;
  level: Localized;
  title: Localized;
  overview: Localized;
  outcomes: Localized[];
  units: GoogleUnit[];
  studioBrief: Localized;
  deliverable: Localized;
  guardrail: Localized;
  resources: GoogleResource[];
};

const unit = (title: Localized, objective: Localized, practice: Localized): GoogleUnit => ({ title, objective, practice });
const publicResource = (title: string, url: string, note: Localized): GoogleResource => ({ title, url, access: "public-link", license: "Public link — verify resource terms", note });
const openResource = (title: string, url: string, note: Localized): GoogleResource => ({ title, url, access: "open", license: "CC BY 4.0 / Apache 2.0", note });

